import { Capacitor } from '@capacitor/core';
export class CapacitorSQLiteKyselyConnection {
    #config;
    #database;
    #sqlite;
    constructor(config, db, sqlite) {
        this.#config = config;
        this.#database = db;
        this.#sqlite = sqlite;
    }
    get db() {
        return this.#database;
    }
    async executeQuery(compiledQuery) {
        const isTransaction = (await this.#database.isTransactionActive()).result;
        if (compiledQuery.sql.toLowerCase().includes('select') || isTransaction) {
            return this.executeSelectOrTransactionQuery(compiledQuery);
        }
        const { changes } = await this.#database.run(compiledQuery.sql, compiledQuery.parameters, true, 
        // everything or nothing is only supported
        compiledQuery.sql.toLowerCase().includes('returning') ? 'all' : 'no');
        if (Capacitor.getPlatform() === 'web') {
            this.#sqlite.saveToStore(this.#config.name);
        }
        return {
            numAffectedRows: changes?.changes,
            insertId: changes?.lastId,
            rows: changes?.values,
        };
    }
    async executeSelectOrTransactionQuery(compiledQuery) {
        const { values } = await this.#database.query(compiledQuery.sql, compiledQuery.parameters);
        return {
            rows: values,
        };
    }
    streamQuery(compiledQuery, chunkSize) {
        throw new Error('Streaming is not supported with SQLite3');
    }
}
